-- Step 6 of 6 — database user for Keigan's managed identity (run as the server's Entra admin)
-- Generated by backend/scripts/generate_azure_sql_ddl.py on 2026-11-23 03:50 UTC from the Keigan entities.
-- Do not edit by hand: change the entity, regenerate, and review the diff.
SET NOCOUNT ON;
GO

-- Needs the SQLCMD variable KeiganIdentityName = display name of Keigan's user-assigned managed identity (e.g. id-keigan-prod).
--   sqlcmd: pass -v KeiganIdentityName=id-keigan-prod (sqlcmd stops with 'scripting variable not defined' if it is missing).
--   SSMS / Azure Data Studio: turn on Query > SQLCMD Mode and uncomment the next line.
-- :setvar KeiganIdentityName id-keigan-prod
PRINT N'Creating the database user for $(KeiganIdentityName)';
GO

IF NOT EXISTS (SELECT 1 FROM sys.database_principals WHERE name = N'$(KeiganIdentityName)')
    CREATE USER [$(KeiganIdentityName)] FROM EXTERNAL PROVIDER WITH DEFAULT_SCHEMA = [keigan];
GO

-- Day-to-day access: read and write data in Keigan's schema only.
GRANT SELECT, INSERT, UPDATE, DELETE ON SCHEMA::[keigan] TO [$(KeiganIdentityName)];
GO

-- Optional: lets the Helm migration job apply future schema changes itself (python -m alembic upgrade head).
-- Leave commented out if your DBAs apply schema changes with these scripts instead.
-- GRANT ALTER ON SCHEMA::[keigan] TO [$(KeiganIdentityName)];
-- GRANT CREATE TABLE TO [$(KeiganIdentityName)];
-- GRANT REFERENCES TO [$(KeiganIdentityName)];
SELECT N'Keigan identity $(KeiganIdentityName) can now use the database.' AS result;
GO
